const badges=[];for(const [x,z] of [[-13,-21],[10,-13],[-9,-3],[13,7],[-12,18],[8,23]]){const g=new THREE.Group();g.position.set(x,1.15,z);scene.add(g);const star=new THREE.Mesh(new THREE.OctahedronGeometry(.42,0),mats.gold);star.castShadow=true;g.add(star);const halo=new THREE.Mesh(new THREE.TorusGeometry(.62,.035,8,24),new THREE.MeshBasicMaterial({color:0xffe083}));halo.rotation.x=Math.PI/2;g.add(halo);badges.push({group:g,got:false,phase:Math.random()*8})}

const hud=$('#hud'),overlay=$('#overlay'),crosshair=$('#crosshair'),mobile=$('#mobile');let running=false,paused=false,converted=false,finished=false,seconds=90,got=0,tags=0,foam=1,foamCooldown=0,dash=0,fireClock=0,yaw=0,pitch=0,toastClock=0;
const keys={},shots=[],sparkles=[];let audio=null,mute=false;
function sound(freq=440,dur=.08,type='sine',vol=.035){if(mute)return;try{audio??=new AudioContext();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch{}}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');toastClock=2.1}
function setOverlay(title,subtitle,button='Play again'){overlay.classList.remove('hidden');overlay.querySelector('.card').innerHTML=`<div class="eyebrow">AFTER-SCHOOL ARCADE</div><h1>${title}</h1><p>${subtitle}</p><div class="rules"><div class="rule"><b>Festival badges</b>${got} / ${badges.length} collected</div><div class="rule"><b>Club friends</b>${bots.filter(b=>b.stun<0).length} joined your team</div></div><button class="cta" id="again">${button}</button><p class="fine">No one gets hurt — just foam, glitter, and good sportsmanship.</p>`;$('#again').onclick=()=>location.reload()}
$('#start').addEventListener('click',()=>{overlay.classList.add('hidden');hud.classList.remove('hidden');crosshair.classList.remove('hidden');mobile.classList.remove('hidden');running=true;if(innerWidth>700)renderer.domElement.requestPointerLock?.();sound(660,.1,'triangle')});
$('#sound').addEventListener('click',()=>{mute=!mute;$('#sound').textContent=mute?'♪ sound off':'♪ sound on'});
document.addEventListener('pointerlockchange',()=>{if(!document.pointerLockElement&&running&&!finished){paused=true;running=false;setOverlay('PAUSED','Take a breath, then jump back into the festival.','Resume run');$('#again').onclick=()=>{overlay.classList.add('hidden');running=true;paused=false;if(innerWidth>700)renderer.domElement.requestPointerLock?.()}}});
document.addEventListener('mousemove',e=>{if(document.pointerLockElement){yaw-=e.movementX*.0022;pitch=THREE.MathUtils.clamp(pitch+e.movementY*.0018,-.4,.48)}});
document.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Space'&&running)shoot(true);if(e.code==='ShiftLeft'||e.code==='ShiftRight')dash=Math.max(dash,.16);if(e.code==='Escape'&&running){running=false;paused=true;setOverlay('PAUSED','The festival can wait. Ready when you are.','Resume run');$('#again').onclick=()=>{overlay.classList.add('hidden');running=true;paused=false}}});document.addEventListener('keyup',e=>keys[e.code]=false);
renderer.domElement.addEventListener('mousedown',e=>{if(e.button===0&&running)shoot(true)});
// Touch joystick plus drag-to-look; safe-area friendly on phones and tablets.
let stickX=0,stickY=0,touchLook=null;$('#stick').addEventListener('pointerdown',e=>{e.preventDefault();$('#stick').setPointerCapture(e.pointerId);updateStick(e)});$('#stick').addEventListener('pointermove',e=>{if(e.buttons)updateStick(e)});$('#stick').addEventListener('pointerup',()=>{stickX=stickY=0;$('#nub').style.transform='translate(0,0)'});function updateStick(e){let r=$('#stick').getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),d=Math.hypot(dx,dy),k=Math.min(1,42/Math.max(1,d));stickX=dx*k/42;stickY=dy*k/42;$('#nub').style.transform=`translate(${stickX*34}px,${stickY*34}px)`}
$('#fire').addEventListener('pointerdown',e=>{e.preventDefault();shoot(true)});renderer.domElement.addEventListener('touchstart',e=>{if(e.touches.length===1)touchLook={x:e.touches[0].clientX,y:e.touches[0].clientY}},{passive:true});renderer.domElement.addEventListener('touchmove',e=>{if(touchLook&&e.touches.length===1){const t=e.touches[0];yaw-=(t.clientX-touchLook.x)*.006;pitch=THREE.MathUtils.clamp(pitch+(t.clientY-touchLook.y)*.004,-.4,.48);touchLook={x:t.clientX,y:t.clientY}}},{passive:true});renderer.domElement.addEventListener('touchend',()=>touchLook=null);
function addShot(origin,dir,friendly){const material=new THREE.MeshBasicMaterial({color:friendly?0x64efff:0xff72cf});const orb=new THREE.Mesh(new THREE.SphereGeometry(friendly?.18:.22,10,8),material);orb.position.copy(origin);scene.add(orb);const glow=new THREE.PointLight(friendly?0x4de8ff:0xff52bb,1.2,3);orb.add(glow);shots.push({mesh:orb,vel:dir.clone().multiplyScalar(friendly?24:11),friendly,life:3})}
function shoot(fromPlayer){if(!running||foamCooldown>0)return;foamCooldown=.24;const direction=new THREE.Vector3(Math.sin(yaw)*Math.cos(pitch),Math.sin(pitch),Math.cos(yaw)*Math.cos(pitch)).normalize();const origin=player.root.position.clone().add(new THREE.Vector3(0,1.45,0)).add(direction.clone().multiplyScalar(.75));addShot(origin,direction,true);sound(440+Math.random()*80,.07,'triangle',.022)}
function burst(pos,color=0xffd978){for(let i=0;i<7;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.055+Math.random()*.06,7,6),new THREE.MeshBasicMaterial({color,transparent:true}));m.position.copy(pos);scene.add(m);sparkles.push({mesh:m,vel:new THREE.Vector3((Math.random()-.5)*3,Math.random()*3,(Math.random()-.5)*3),life:.5+Math.random()*.45})}}
function convertPlayer(){if(converted)return;converted=true;player.shirt.color.set(0xff70ad);player.shirt.emissive=new THREE.Color(0x571633);player.gun.children[1].material=mats.pink;$('#status').innerHTML='<b>HONORARY CLUB MEMBER</b> · glitter makeover complete';$('#objective').innerHTML='Makeover complete! Keep collecting <span>festival badges</span> — the club is cheering you on.';toast('✨ Surprise makeover! You’re in the club!');sound(720,.28,'sine',.06);burst(player.root.position.clone().add(new THREE.Vector3(0,2,0)),0xff74c2)}
function tagBot(bot){bot.stun=bot.stun<0?bot.stun:bot.stun+1;bot.actor.root.userData.flash=.25;burst(bot.actor.root.position.clone().add(new THREE.Vector3(0,1.4,0)),0x70efff);sound(590,.1,'triangle');if(bot.stun>=3){bot.stun=-1;bot.tagger=false;bot.actor.shirt.color.set(0x7ce2bd);toast('🎉 A new festival friend!');$('#status').innerHTML='<b>TEAM SPIRIT</b> · foam tags: '+bots.filter(b=>b.stun<0).length+' / '+bots.length}}

